// `WorktreeRemove`: removes a worktree only when a session made no file in it.
// The check is `git status --ignored`. A file that the create hook copied and that is unchanged does not count.

import fs from "node:fs";
import {
  BRANCH_PREFIX,
  sessionFiles,
  type WorktreePayload,
} from "../domain/worktree.ts";
import { NOT_IN_REPO_DIR } from "../prompts.ts";
import { unchangedCopies } from "./copied.ts";
import { git, mainRoot } from "./git.ts";

/** The result of the hook: `removed`, or the files of the session that keep the worktree, or an error text. */
export type Removed =
  | { removed: true }
  | { kept: string[] }
  | { error: string };

/** Removes the worktree at `worktree_path` when `git status --ignored` shows no file that a session made. */
export const remove = async ({
  worktree_path: dir,
}: WorktreePayload): Promise<Removed> => {
  if (!dir || !fs.existsSync(dir)) return { removed: true };
  const root = mainRoot(dir);
  if (!root) return { error: NOT_IN_REPO_DIR({ dir }) };
  const status = git(dir, [
    "status",
    "--porcelain=v1",
    "-z",
    "--ignored",
    "-uall",
  ]);
  if (!status.ok) return { error: `git status failed: ${status.err.trim()}` };
  // Only a file that the create hook copied, and that is unchanged, is not work of a session.
  const copied = await unchangedCopies(dir);
  const files = sessionFiles(status.out, copied);
  if (files.length > 0) return { kept: files };
  const branch = git(dir, ["symbolic-ref", "--short", "HEAD"]).out.trim();
  const gone = git(root, ["worktree", "remove", "--force", dir]);
  if (!gone.ok)
    return { error: `git worktree remove failed: ${gone.err.trim()}` };
  // A branch with commits that are not merged stays, because `-d` refuses to delete it.
  if (branch.startsWith(BRANCH_PREFIX)) git(root, ["branch", "-d", branch]);
  return { removed: true };
};
